        content:
          '• Recht & Tierschutz: In Deutschland darf nur töten, wer über die erforderliche Sachkunde und sichere Betäubung (z.B. fachgerechter Betäubungsschlag auf den Hinterkopf unmittelbar gefolgt vom Entbluteschnitt) verfügt — bei Unsicherheit stets Lohnschlachterei oder erfahrenen Sachkundigen hinzuziehen! Vor dem Schlachten ~12 Std. nüchtern setzen (Kropf & Darm leer, Wasser bleibt verfügbar!).\n• Brühen & Rupfen: Ausgeblutetes Huhn ca. 30–60 Sek. in ~60–65 °C heißes Wasser (nicht kochend, sonst reißt die Haut!) tauchen und sofort gegen die Wuchsrichtung rupfen.\n• Ausnehmen & Ausbeinen (Zerlegen): Kropf und Speiseröhre sauber entfernen, Bauchöffnung ohne Darmverletzung öffnen, Eingeweide inkl. Lunge & Bürzeldrüse vollständig entnehmen. Körper kalt auswaschen und 24 Std. bei 2–4 °C reifen lassen. Danach mit scharfem Ausbeinmesser zerlegen: Flügel im Gelenk trennen, Keulen an der Hüftpfanne auslösen (in Ober- und Unterschenkel teilen), beide Brustfilets eng am Brustbein entlang abschaben. Aus der Karkasse (Knochengerüst) entsteht kräftige Hühnerbrühe!\n• Lagerung: Frisch bei 0–4 °C max. 2–3 Tage; vakuumiert bei -18 °C ca. 6–10 Monate haltbar.',
