          'Typische Klimadaten für Mellenbach-Glasbach (~480–520 m ü. NN, Thüringer Schiefergebirge):\n• Sonnenstunden: Rund 1.550–1.580 Std./Jahr. Hauptschub von April (~156 h) bis August (~198 h; Juni/Juli ~205–212 h/Monat bzw. ~6,8 h/Tag). Im Winter (Dez/Jan) nur ~36–46 h/Monat — deshalb Winterkulturen schon bis September großziehen!\n• Niederschlag: Ca. 900–950 mm/Jahr (deutlich feuchter als im Thüringer Becken!). Selbst in trockeneren Frühjahren fallen im Schnitt ~62–76 mm/Monat; Juli/August bringen oft kräftige Schauer (~84–94 mm).\n• Temperatur & Frost: Jahresmittel ~7,5–8,0 °C. Ca. 95–105 Frosttage/Jahr; späte Bodenfröste sind bis Mitte/Ende Mai (Eisheilige ~20. Mai) möglich.\n• Hauptwindrichtung: Überwiegend Südwest bis West (SW/W). Offene Beete im Oberen Garten profitieren enorm von einer Beeren-/Nusshecke am Westrand, während das Wohnhaus den Unteren Süd-Garten vor Nord- und Ostwinden abschirmt.',
        source: 'DWD-Klimareferenzwerte Thüringer Schiefergebirge / Open-Meteo Standortdaten',
        isVerifiedSource: true,
