        content:
          'Kleine Strukturelemente verwandeln Hof & Hang in eine sichere Heimat für nützliche Wildtiere:\n• Igel (Schnecken- & Käferjäger): Zäune rund um den Garten mit mindestens 10x10 cm Durchschlüpfen („Igelautobahn“) versehen. In ruhiger Ecke hinter Schuppen/Sträuchern einen Laub- & Reisighaufen oder ein trockenes Igelhaus als Winterquartier belassen. WICHTIG: Niemals einen Mähroboter in der Dämmerung oder nachts fahren lassen (schwere Schnittverletzungen bei Igeln!) und vor dem Freischneider/Häckseln Haufen prüfen.\n• Singvögel & Greifvogel-Balance: Heimische Beerengehölze (Holunder, Felsenbirne, Weißdorn, Hasel), ganzjährige flache Vogeltränken (alle 2–3 Tage heiß reinigen!) und Nistkästen (Meisen: 26–32 mm Flugloch nach Ost/Südost gerichtet). Achtung beim Verlegen von Hühner- & Beerenschutznetzen: straff spannen statt lose auf den Boden hängen lassen, damit sich Vögel & Igel nicht verheddern!\n• Zauneidechsen & Blindschleichen: Eine sonnige Trockenmauer oder ein Lesesteinhaufen am Südhang neben Sandlinsen bietet Wärmeplätze & Eiablage.\n• Fledermäuse (Mückenjäger): Flache Fledermauskästen unter dem Dachüberstand von Wohnhaus/Scheune (mind. 3–4 m hoch, freie Anflugschneise) und abends blühende Nachtkerzen/Geißblatt ziehen Nachtfalter als Nahrung an.',
