        content:
          'Wann und wie man gräbt, entscheidet über die Bodenstruktur der nächsten 5 Jahre:\n• FINGERPROBE VOR DEM GRABEN (Pflicht bei Lehm/Schiefer!): Eine Handvoll Boden aus 10–15 cm Tiefe fest zur Kugel drücken:\n  – Zerfällt die Kugel bei leichtem Fingerdruck krümelig -> ideal „erdfeucht“, perfekt zum Graben, Sieben & Planieren!\n  – Lässt sie sich wie Knete schmierig zu einer glänzenden Wurst rollen und macht nasse Hände -> VIEL ZU NASS! Graben oder Befahren verdichtet den Boden steinhart („Schmierschicht“). Lieber 3–5 trockene Tage warten.\n  – Staubt hart wie Beton -> zu trocken, abends leicht wässern und am nächsten Morgen graben.\n• Beste Jahreszeit für Erd- & Mauerbau: Spätsommer/Frühherbst (trockenster Boden, neu aufgeschüttete Terrassen & Wege können sich über Winterregen natürlich setzen, bevor im Frühjahr gepflanzt wird) oder ab Mitte April nach Abtrocknung der Schneeschmelze.\n• Sofortiger Erosionsschutz am Hang: Frisch modellierte Böschungen oder frisch aufgeschüttete Beete im Schwarzatal nie wochenlang nackt liegen lassen — der nächste Platzregen schwemmt die beste Erde weg! Steilere Böschungen direkt nach Bauende mit Jute-/Kokosgewebe (verrottet in 2–3 Jahren) fixieren und sofort mit tiefwurzelnder Klee-Gras-Mischung oder Phacelia einsäen.',
