        category: 'Garten- & Landschaftsbau',
        content:
          'Wenn der Gartenhang zum Wohnhaus hin abfällt (wie beim Oberen Garten in Mellenbach), erfordert das anfangs etwas Respekt vor Regenwasser — bietet gestalterisch aber einen RIESENVORTEIL:\n• DIE „GRÜNE BÜHNE“ (Amphitheater-Effekt!): Anders als bei Grundstücken, die vom Haus weg abfallen, schaut ihr von der Terrasse und aus den Fenstern direkt AUF eure Gartenebenen! Jede Trockenmauer, jedes Blütenbeet, jeder Rosenbogen und jeder kleine Bachlauf/Teich wird zum lebendigen Gemälde direkt vor dem Haus.\n• SCHUTZ DES HAUSES GEHT VOR (Wichtigste Regel bei Hang zum Haus!): Bei Starkregen darf Oberflächenwasser niemals ungehindert gegen die Hauswand oder über die Terrasse schießen:\n  1. Fangmulde / Sickerrinne am Hangfuß: 1–2 m vor Terrasse/Haus eine flache Kiesrinne, Aco-Entwässerungsrinne oder bepflanzte Mulde mit leichtem Seitengefälle anlegen, die Hangwasser kontrolliert seitlich am Haus vorbei leitet.\n  2. Gefälle der Terrasse: Terrassenbelag immer 1,5–2 % VOM Haus weg neigen.\n  3. Keine geschlossene Betonwand ohne Durchlass direkt vor dem Haus — staut sonst Hangwasser wie ein Damm!\n• MIKROKLIMA-BONUS: Kalte Frostluft sinkt nachts nach unten ab. Der obere und mittlere Hang ist deshalb oft frostsicherer bei Spätfrösten als eine geschlossene Talmulde — perfekt für Obstbäume & Beeren! Unten am Fuß des Hangs entsteht dagegen bei Südausrichtung ein windgeschützter, sonnenwarmer Sitz- und Kräuterplatz.\n• OPTIMALE ZONIERUNG VON UNTEN NACH OBEN:\n  – Hangfuß (nah am Haus/Terrasse): Duft- & Küchenkräuter, gemütliche Sitzecke, Kiesrinne/kleiner Wasserspiegel.\n  – Mittelhang (terrassenförmig gestaffelt): Trockenmauern mit Sonnenstauden, Gemüse-Hochbeete, kleine Naschbeeren-Nische.\n  – Oberhang / Hangkrone: Obstbäume, Beerenhecke (als Windbremse), Aussichtsbank mit Blick übers Haus ins Tal, Wildblumen- & Glühwürmchen-Saum.',
