        content:
          'Kaninchen sind neugierige, hochsoziale Dämmerungstiere — mit dem richtigen Blick versteht man genau, wie es ihnen geht:\n• KÖRPERSPRACHE ENTSCHLÜSSELN:\n  – „Binky“ (plötzlicher Luftsprung mit Kopfschütteln & halber Drehung): pures Überglücks-Zeichen!\n  – Seitlich umfallen („Flop“) mit ausgestreckten Hinterläufen: Tiefenentspannung pur (sie fühlen sich 100 % sicher!).\n  – Leises Zähneknuspern beim Streicheln: wie Schnurren bei der Katze. ACHTUNG — lautes, gepresstes Zähneknirschen in kauernder Haltung: starkes Schmerzzeichen (sofort Bauch/Zähne prüfen!).\n  – Starkes Aufstampfen mit den Hinterläufen: Alarmruf bei Gefahr (Katze, Greifvogel, Marder oder fremder Geruch).\n  – Kinn an allem reiben: „Das gehört mir!“ — über harmlose Duftdrüsen unter dem Kinn markieren sie ihr Revier.\n• PRO-TIPPS GEGEN AUSBRUCH & LANGEWEILE:\n  – Vollflächiger Untergrabschutz: Statt nur Zäune einzugraben, am besten vollflächig starkes Volierengitter (~16–19 mm, verzinkt) 15–20 cm tief unter der gesamten Wiese verlegen und Erde + Rasen drüber — so können Kaninchen nach Herzenslust buddeln, ohne sich jemals unter dem Zaun durchzugraben!\n  – Beschäftigungs-Ideen fast gratis: Papprollen mit Heu & getrockneten Kräutern füllen, frische ungespritzte Obst-/Hasel-/Weidenäste (Zahnabrieb + Spielzeug!), erhöhte Aussichtsplattform aus Holz (Kaninchen sitzen unglaublich gern erhöht als „Wachposten“!), oder Futter auf einer Schnur leicht erhöht aufhängen.',
