          'Auch auf ~500 m Höhenlage im Thüringer Schiefergebirge lässt sich die Erntezeit ohne teure Heizung um 2–3 Monate strecken:\n• „WINTER SOWING“ (Genialer Ami-/Nordland-Trick für März-Frost!):\n  – Durchsichtige 5-Liter-Wasserkanister oder tiefe Plastikboxen mit Deckel rundherum bis auf ein kleines Scharnier aufschneiden, unten Drainagelöcher stechen, 10 cm Anzuchterde einfüllen, Spinat, Salat, Kohl, Ringelblumen oder Rucola einsäen, zukleben, Deckel/Schraubverschluss ABNEHMEN (Regen & Luft kommen rein!) und im Februar/März einfach draußen hinstellen! Die Minigewächshäuser schützen vor Starkregen & Vögeln, und die Keimlinge schlüpfen automatisch genau zum richtigen Zeitpunkt extrem abgehärtet!\n• SCHWARZE WÄRMESPEICHER IM GEWÄCHSHAUS: 2–3 alte schwarz gestrichene Wasserkanister oder dunkle Schieferplatten im Gewächshaus aufstellen — nehmen tagsüber Sonnenwärme auf und geben sie in kalten April-/Mainächten frostpuffernd wieder ab!\n• FRÜHBEETKASTEN AUS ALTEN FENSTERN: Ein einfacher Rahmen aus Lärchenbohlen (hinten 40 cm hoch, vorn 30 cm zur Sonne geneigt) mit einem alten ausrangierten Holzfenster drauf liefert ab März knackigen Radieschen & Kopfsalat — 4 Wochen vor dem Freiland!\n• HERBST-AUSSAAT FÜR WINTER-FRISCHE: Mitte August bis Anfang September Feldsalat, Postelein (Winterportulak — wächst noch bei +2 °C!), Winterspinat und Asiasalate säen — unter einem einfachen Vlies-Tunnel erntet ihr bis Weihnachten und oft schon wieder ab Februar!',
