        content:
          'Die wohl beste Erfindung für rückenschonenden, hochproduktiven Hausgartenbau (bekannt durch Charles Dowding):\n• WARUM NICHT UMGRABEN? Beim tiefen Umgraben dreht man die empfindlichen Bodenorganismen (oben Sauerstoff-Liebhaber, unten sauerstoffarm) auf den Kopf, zerstört Pilznetzwerke und holt jahrelang schlummernde Unkrautsamen ans Licht!\n• SO ENTSTEHT EIN NEUES BEET AUS WIESE IN 1 NACHMITTAG (Pappe-Kompost-Sandwich):\n  1. Wiese/Unkraut im gewünschten Beetbereich ganz kurz abmähen (nichts rausreißen!).\n  2. Unbeschichtete, braune Wellpappe (alle Klebebänder & Etiketten entfernen; KEINE hochglanzbedruckten Kartons!) großzügig überlappend (mind. 15 cm Überlappung!) flach auslegen und einmal richtig nass wässern.\n  3. Auf die nasse Pappe direkt 10–15 cm reifen Kompost (oder gut verrottete Kompost-Erde-Mischung) verteilen und glatt harken — die Seiten ggf. mit Holzbrettern oder Steinen einfassen.\n  4. FERTIG — ihr könnt SOFORT in die obere Kompostschicht säen oder Jungpflanzen setzen!\n• WAS PASSIERT DARUNTER? Die Pappe nimmt Gras & Löwenzahn für ca. 3–4 Monate das Licht -> sie sterben ab und verrotten zu Dünger. Regenwürmer lieben feuchte Zellulose, fressen die Pappe auf und ziehen den Kompost selbsttätig tief in den Boden ein! Nach 1 Jahr habt ihr krümeligsten Traum-Boden — mit 80 % weniger Unkraut!',
