          'Für einen schokobraun-türkisen Eierkorb mit Charakter:\n• MARANS:\n  – Legeleistung: ~170–200 tief-schokobraune Eier/Jahr (60–65 g). Besonderheit: Sehr dicke, porenarme Eischale — die Eier bleiben deutlich länger frisch und Keime dringen schwerer ein!\n  – Fleischleistung: Hahn ~3,5–4,0 kg, Henne ~2,5–3,0 kg — in Frankreich für extrem saftiges Delikatess-Fleisch berühmt.\n  – Verhaltensprofil: Ruhig, selbstbewusst, ausgeglichen, fliegt kaum; mäßig brutfreudig.\n  – Anfälligkeiten: Leicht befiederte Läufe/Zehen! In dauerhaft schlammigen Ausläufen können Schmutzklumpen an den Füßen kleben bleiben und Kalkbeinmilben begünstigen -> trockene Einstreu & drainierte Auslaufzonen sichern.\n• ARAUCANA (Original, schwanzlos):\n  – Legeleistung: ~170–190 türkisgrüne bis bläuliche Eier/Jahr (ca. 50–55 g, großer Dotteranteil).\n  – Fleischleistung: Hahn ~2,0–2,5 kg, Henne ~1,6–2,0 kg — eher leichter Körperbau (Lege-Fokus).\n  – Verhaltensprofil: Lebhaft, wachsam, aufmerksam gegen Greifvögel, oft neugierig-frech und flugfreudiger (Zaun ~1,4–1,6 m).\n  – Anfälligkeiten: Durch Erbsenkamm und fehlende Schwanzfedern sehr winterhart; in der Reinzucht aufpassen (das „Bommel“-Gen für Ohrbüschel ist im Doppelpack bei Küken oft letal — als Legehennen aber kerngesund!).',
