          'Zwei alte deutsche Kulturrassen für Genießer, die sanfte Tiere lieben:\n• DEUTSCHES LACHSHUHN:\n  – Legeleistung: ~160–180 cremefarbene bis gelbliche Eier/Jahr (~55 g, legt brav auch im Winter).\n  – Fleischleistung: Hahn ~3,5–4,0 kg, Henne ~2,5–3,25 kg — gilt als eine der feinsten, zartesten Fleischrassen überhaupt!\n  – Verhaltensprofil: Ausgesprochen sanftmütig, friedfertig, ruhig, fliegt kaum; brütet selten.\n  – Anfälligkeiten: WICHTIG IN GEMISCHTEN HERDEN — durch ihre extreme Gutmütigkeit stehen Lachshühner in der Hackordnung oft ganz unten und werden von dominanten Rassen (Hybriden, Italiener, Marans) vom Trog verdrängt -> immer mehrere ruhige Tiere zusammen halten & zweite Futterstelle anbieten! Zudem 5 Zehen + Fußbefiederung (trocken halten gegen Kalkbeine).\n• SUNDHEIMER:\n  – Legeleistung: ~200–220 hellbraune Eier/Jahr (ca. 55 g, spitze im Winter!).\n  – Fleischleistung: Hahn ~3,0–3,5 kg, Henne ~2,0–2,5 kg — sehr schöner Fleischansatz.\n  – Verhaltensprofil: Ruhig, sehr zutraulich, pflegeleicht, fliegt nicht hoch.\n  – Anfälligkeiten: Sehr robust im Mittelgebirge; ebenfalls leicht befiederte Füße im Blick behalten und nicht überfüttern.',
