        content:
          'Kontrastprogramm — von der Mini-Glucke über den agilen Weißleger bis zur Einordnung von Hybriden:\n• ZWERG-WYANDOTTEN:\n  – Legeleistung: ~160–180 hellbraune Eier/Jahr (~40–45 g — im Verhältnis zur Größe erstaunlich groß!).\n  – Fleischleistung: ~1,0–1,3 kg (reine Eier-/Gartenrasse).\n  – Verhaltensprofil: Ruhig, freundlich, scharrt wenig Beete um, fliegt kaum — und ist eine der besten & zuverlässigsten GLUCKEN für Naturbrut!\n  – Anfälligkeiten: Durch den flachen Rosenkamm null Erfrierungsgefahr im Winter; neigt manchmal zu hartnäckiger Brutlust („Entglucken“ nötig, falls kein Nachwuchs gewünscht).\n• ITALIENER (Klassische Legerasse):\n  – Legeleistung: ~200–220 große schneeweiße Eier/Jahr (58–62 g).\n  – Fleischleistung: Hahn ~2,2–3,0 kg, Henne ~1,7–2,5 kg (eher schlank).\n  – Verhaltensprofil: Sehr aktiv, schnell, vorsichtig/scheuer, hervorragende Futtersucher im großen Gelände — ABER sehr flugfreudig (fliegt locker über 1,5 m Zäune!).\n  – Anfälligkeiten: Hähne & Hennen haben sehr große Einfachkämme -> bei strengem Frost im Schwarzatal mit Vaseline gegen Erfrierungen schützen.\n• HINWEIS ZU LEGEHYBRIDEN (z.B. Lohmann Brown / Bovan): Legen zwar ~280–320 Eier/Jahr, sind aber Hochleistungskreuzungen — brauchen zwingend exakt abgestimmtes Legemehl und werden oft schon ab dem 2. Jahr anfällig für Legedarm-Entzündungen, Windeier und Erschöpfung. Rassehühner legen moderater, bleiben dafür oft 5–7 Jahre vital!',
