        content:
          'Die beiden bewährtesten Wirtschaftsrassen für eine unkomplizierte, ruhige Selbstversorgung:\n• HELLE GROSSSILBER:\n  – Leistung & Gewicht: Endgewicht ~4,25–5,25 kg; Schlachtreife ab ca. 6 Monaten; hervorragende Schlachtausbeute (~58–60 %) mit feinfaserigem, saftigem Fleisch. Durchschnittlich 6–8 Jungtiere pro Wurf (Jungtiere werden schwarz geboren und „silbern“ erst nach Wochen um!).\n  – Verhaltensprofil: Sehr ruhiges, ausgeglichenes, gelassenes Wesen, zuverlässige Mütter.\n  – Anfälligkeiten: Extrem robust & winterhart; lediglich auf saubere, weiche Einstreu achten, damit bei ~5 kg Gewicht keine wunden Läufe (Pododermatitis) entstehen, und Kraftfutter knapp halten (Fettansatz im Bauchraum vermeiden!).\n• WEISSE & ROTE NEUSEELÄNDER:\n  – Leistung & Gewicht: Endgewicht ~4,0–5,0 kg; sehr frühreif (bereits mit 5–6 Monaten schlachtreif mit vollem Rücken & dicken Keulen!), große Würfe (oft 7–9 Junge) und viel Milch.\n  – Verhaltensprofil: Ausgeglichen, neugierig, verhältnismäßig stresstolerant und sehr gute, schützende Häsinnen.\n  – Anfälligkeiten: Rote Neuseeländer sind sehr wetterhart; bei Weißen Neuseeländern (rote Augen/Albinismus) im Hochsommer pralle direkte Mittagssonne vermeiden (blendempfindlich!). Beide Rassen vertragen Hitze > 28 °C schlechter als Kälte.',
