        content:
          'Gezielte, giftfreie Taktiken gegen die 4 häufigsten Gartenplagen:\n• WÜHLMÄUSE (ovale Gänge hochkant, flache Erdhaufen mit seitlichem Ausgang — im Gegensatz zum Maulwurf mit rundem Kegel und geschützter Art!):\n  – Junge Obstbäume beim Pflanzen ZWINGEND in einen engmaschigen Drahtkorb (Sechseckgeflecht 13–16 mm, unverzinkt damit er nach 6–8 Jahren durchrostet!) setzen. Knoblauch-/Kaiserkrone-Duft hilft nur kurzzeitig; Fallen (bayerische/Topcat-Falle mit sauber gewaschenen Händen/Handschuhen stellen) regulieren effektiv.\n• SCHNECKEN: Bierfallen weglassen (locken Schnecken aus 50 m Entfernung der Nachbarn an!). Stattdessen: Abends absammeln, morgens statt abends gießen, Kupferband am Hochbeet, Laufenten oder im Extremfall selektives Eisen-III-Phosphat.\n• FROSTSPANNER (Raupen an Obstblüten): Ende September bis Februar Leimringe um glatte Baumstämme und Baumpfähle binden (Achtung: im Frühjahr abnehmen, damit Nützlinge wieder hochklettern können!).\n• BLATTLÄUSE: Nicht beim ersten Auftreten eingreifen -> Marienkäfer & Florfliegen brauchen 7–10 Tage Vorlauf! Bei Überbefall kräftiger Wasserstrahl oder 1 % Schmierseifen-Spiritus-Lösung (nur abends außerhalb des Bienenflugs!).',
